<div class="page-head"><div><h1>Orders</h1><p class="muted"><?= number_format($pg['total']) ?> orders. Orders are independent of the product quota — deactivating a product never changes past orders.</p></div></div>
<form class="filters-bar" method="get"><label class="sr" for="oq">Search</label><input id="oq" type="search" name="q" value="<?= e(get('q')) ?>" placeholder="Order #, email, name">
<label class="sr" for="os">Status</label><select id="os" name="status"><option value="">All statuses</option><?php foreach (ORDER_STATUSES as $k => $l): ?><option value="<?= $k ?>" <?= get('status') === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach ?></select><button class="btn btn-sm">Filter</button></form>
<div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Date</th><th>Customer</th><th>Items</th><th>Total</th><th>Payment</th><th>Status</th><th>Shipping</th></tr></thead><tbody>
<?php foreach ($orders as $o): ?><tr><td><a class="strong" href="/admin/orders/<?= (int) $o['id'] ?>/">#<?= e($o['number']) ?></a></td><td><?= e(fmt_date($o['created_at'], true)) ?></td><td><?= e($o['name']) ?><br><span class="small muted"><?= e($o['email']) ?></span></td><td><?= (int) val('SELECT SUM(quantity) FROM order_items WHERE order_id = ?', [$o['id']]) ?></td><td><?= e(money((int) $o['total_cents'])) ?></td><td><span class="badge badge-<?= e($o['payment_status']) ?>"><?= e(PAYMENT_STATUSES[$o['payment_status']] ?? '') ?></span><br><span class="small muted"><?= e($o['payment_method']) ?></span></td><td><span class="badge badge-<?= e($o['status']) ?>"><?= e(ORDER_STATUSES[$o['status']] ?? '') ?></span></td><td class="small"><?= e(SHIPPING_STATUSES[$o['shipping_status']] ?? '') ?></td></tr><?php endforeach ?>
<?php if (!$orders): ?><tr><td colspan="8" class="empty-cell">No orders yet.</td></tr><?php endif ?>
</tbody></table></div>
<?= pager_html($pg, '/admin/orders/') ?>
